//! The finisher (spec 135 §5): the deterministic chores before a pull request, done in-process with the same functions the
//! drift tests use. It regenerates the reference, the ecosystem files and the compiled specs, checks the slice's tracker row,
//! prints the gates (it runs none: a new process start is a gate change, F1b) and can print a pull request body.

use crate::slice_claims::{self, Out};
use crate::tracker;
use std::path::Path;

/// One generated file: its path in the checkout and what the program generates for it now.
pub struct Generated {
    pub path: &'static str,
    pub text: Result<String, String>,
}

/// The reference files of `crates/delphi/tests/docs.rs`, generated by this binary.
pub fn reference(repo: &Path) -> Vec<Generated> {
    vec![
        Generated { path: "docs/reference/cli.md", text: Ok(crate::docs_cmd::cli_markdown()) },
        Generated { path: "docs/reference/delphi.1", text: Ok(crate::docs_cmd::man_page()) },
        Generated { path: "docs/reference/catalog.md", text: crate::docs_cmd::catalog_markdown(repo) },
        Generated { path: "docs/reference/execute-names.md", text: crate::docs_cmd::execute_names_markdown(repo) },
        Generated { path: "docs/reference/harness-coverage.md", text: Ok(delphi_engine::coverage::markdown()) },
    ]
}

/// What a pass found: the files that drifted (or were rewritten), and the generators that failed.
#[derive(Debug, Default, PartialEq, Eq)]
pub struct Sync {
    pub changed: Vec<String>,
    pub errors: Vec<String>,
}

/// Compare each file with what is generated; unless `check`, write the ones that differ.
pub fn sync(repo: &Path, files: Vec<Generated>, check: bool) -> Sync {
    let mut s = Sync::default();
    for g in files {
        let text = match g.text {
            Ok(t) => t,
            Err(e) => {
                s.errors.push(format!("{}: {}", g.path, e));
                continue;
            }
        };
        let p = repo.join(g.path);
        if std::fs::read_to_string(&p).ok().as_deref() == Some(text.as_str()) {
            continue;
        }
        if !check {
            if let Err(e) = std::fs::write(&p, &text) {
                s.errors.push(format!("{}: {}", g.path, e));
                continue;
            }
        }
        s.changed.push(g.path.to_string());
    }
    s
}

/// The version in `crates/delphi/Cargo.toml` of a checkout.
fn checkout_version(repo: &Path) -> Option<String> {
    let t = std::fs::read_to_string(repo.join("crates/delphi/Cargo.toml")).ok()?;
    let pkg = t.split("[package]").nth(1)?;
    pkg.lines().find_map(|l| l.trim().strip_prefix("version").map(|v| v.trim_start_matches([' ', '=']).trim().trim_matches('"').to_string()))
}

pub const GATES: [&str; 3] = [
    "CARGO_INCREMENTAL=0 CARGO_PROFILE_DEV_DEBUG=0 cargo test --workspace --locked",
    "cargo clippy --workspace --all-targets --locked -- -D warnings",
    "cargo run -q --locked -p delphi -- lint --repo .",
];

pub struct FinishReq<'a> {
    pub repo: &'a Path,
    pub home: &'a Path,
    pub check: bool,
    pub spec: Option<&'a str>,
    pub slice: Option<&'a str>,
    pub body: bool,
    pub now: i64,
}

/// The tracker check (§5.3): the row of the slice, or a finding. `None` when no slice is known.
fn tracker_check(repo: &Path, stem: &str, slice: &str) -> Result<tracker::Row, String> {
    let num = tracker::spec_number(stem).ok_or_else(|| format!("{} has no spec number", stem))?;
    let text = std::fs::read_to_string(tracker::path(repo)).map_err(|e| format!("cannot read the tracker ({}): {}", tracker::PATH, e))?;
    let all = tracker::rows(&text);
    let Some(row) = all.iter().find(|r| r.spec.eq_ignore_ascii_case(&num) && r.slice.eq_ignore_ascii_case(slice)) else {
        return Err(format!("the tracker ({}) has no row for {} {}: add `| {} | {} | <what it does> | <state> |`", tracker::PATH, num, slice, num, slice));
    };
    if tracker::state_unfinished(&row.state) {
        return Err(format!("the tracker row for {} {} (line {}) still says \"{}\": say what was built and verified", num, row.slice, row.line, row.state));
    }
    Ok(row.clone())
}

fn spec_title(repo: &Path, stem: &str) -> String {
    let text = std::fs::read_to_string(repo.join("specs").join(format!("{}.md", stem))).unwrap_or_default();
    text.lines().skip(1).take_while(|l| l.trim() != "---").find_map(|l| l.strip_prefix("title:").map(|t| t.trim().trim_matches('"').to_string())).unwrap_or_else(|| stem.to_string())
}

pub fn finish(r: &FinishReq) -> Out {
    let facts = match slice_claims::git_facts(r.repo) {
        Ok(f) => f,
        Err(e) => return Out { code: 2, out: String::new(), err: e },
    };
    let repo = facts.top.as_path();
    let (mut out, mut err) = (String::new(), String::new());
    let mut finding = false;
    let mut failed = false;
    let version = env!("CARGO_PKG_VERSION");
    if let Some(v) = checkout_version(repo).filter(|v| v != version) {
        err.push_str(&format!("warning: this delphi is {} and the checkout is {}: the reference is what THIS binary generates; run the finisher built from the branch (`cargo run -q -p delphi -- forge finish`)\n", version, v));
    }

    // 1. The reference.
    let s = sync(repo, reference(repo), r.check);
    for c in &s.changed {
        out.push_str(&format!("{} {}\n", if r.check { "drift:" } else { "wrote" }, c));
    }
    for e in &s.errors {
        err.push_str(&format!("error: {}\n", e));
    }
    finding |= r.check && !s.changed.is_empty();
    failed |= !s.errors.is_empty();

    // 2. The ecosystem files.
    let drift = delphi_engine::mcp_hosts::ecosystem_drift(repo, version);
    if !drift.is_empty() {
        if r.check {
            for d in &drift {
                out.push_str(&format!("drift: ecosystem: {}\n", d));
            }
            finding = true;
        } else {
            match delphi_engine::mcp_hosts::write_ecosystem(repo, version) {
                Ok(files) => {
                    for f in files {
                        out.push_str(&format!("wrote {}\n", f.display()));
                    }
                }
                Err(e) => {
                    err.push_str(&format!("error: ecosystem: {}\n", e));
                    failed = true;
                }
            }
        }
    }

    // 3. The compiled specs, through the compiler.
    match crate::spec_compile::compile_in(repo, true) {
        Ok(_) => {}
        Err((1, lines)) if r.check => {
            for l in lines {
                out.push_str(&format!("drift: {}\n", l));
            }
            finding = true;
        }
        Err((1, _)) => match crate::spec_compile::compile_in(repo, false) {
            Ok(line) => out.push_str(&format!("{}\n", line)),
            Err((_, lines)) => {
                for l in lines {
                    err.push_str(&format!("error: {}\n", l));
                }
                failed = true;
            }
        },
        Err((_, lines)) => {
            for l in lines {
                err.push_str(&format!("error: {}\n", l));
            }
            failed = true;
        }
    }
    if out.is_empty() {
        out.push_str("generated files: current\n");
    }

    // 4. The tracker row of the slice.
    let claim = slice_claims::claim_of_branch(repo, r.home, r.now);
    let target: Option<(String, String)> = match (r.spec, r.slice) {
        (Some(sp), Some(sl)) => match delphi_engine::spec_lookup::spec_stems(repo).and_then(|st| delphi_engine::spec_lookup::resolve(&st, sp)) {
            Ok(stem) => Some((stem, sl.to_string())),
            Err(e) => return Out { code: 2, out, err: format!("{}{}", err, e) },
        },
        (None, None) => claim.as_ref().map(|c| (c.spec.clone(), c.slice.clone())),
        _ => return Out { code: 2, out, err: format!("{}name both --spec and --slice, or neither", err) },
    };
    let mut row = None;
    match &target {
        None => out.push_str("tracker: skipped (no --spec/--slice and no live claim on this branch)\n"),
        Some((stem, slice)) => match tracker_check(repo, stem, slice) {
            Ok(rw) => {
                out.push_str(&format!("tracker: {} {}: {}\n", rw.spec, rw.slice, rw.state));
                row = Some(rw);
            }
            Err(e) => {
                err.push_str(&format!("finding: {}\n", e));
                finding = true;
            }
        },
    }

    // 5. The gates: printed, not run.
    out.push_str("gates (not run by the finisher; run them before you commit):\n");
    for g in GATES {
        out.push_str(&format!("  {}\n", g));
    }

    // 6. The body, and the claim renewed.
    if r.body {
        if let Some((stem, slice)) = &target {
            out.push('\n');
            out.push_str(&body(repo, stem, slice, row.as_ref(), &s.changed));
        } else {
            err.push_str("--body needs a slice: pass --spec and --slice, or claim the slice on this branch\n");
            finding = true;
        }
        if let Some(c) = &claim {
            let renewed = slice_claims::claim(&slice_claims::ClaimReq { repo, home: r.home, spec: &c.spec, slice: &c.slice, by: Some(&c.by), ttl_secs: slice_claims::DEFAULT_TTL_SECS, take: false, now: r.now });
            if renewed.code == 0 {
                err.push_str(&renewed.out);
            }
        }
    }
    let code = if failed { 4 } else if finding { 1 } else { 0 };
    Out { code, out, err }
}

/// A pull request body skeleton (§5.4).
pub fn body(repo: &Path, stem: &str, slice: &str, row: Option<&tracker::Row>, regenerated: &[String]) -> String {
    let mut b = format!("{} — slice {}\n\n", spec_title(repo, stem), slice);
    if let Some(r) = row {
        b.push_str(&format!("**Slice:** {}\n\n**Tracker:** {}\n\n", r.content, r.state));
    }
    b.push_str(&format!("Commit trailer: `Implements-Spec: specs/{}.md`\n\n", stem));
    if !regenerated.is_empty() {
        b.push_str("## Regenerated\n\n");
        for f in regenerated {
            b.push_str(&format!("- `{}`\n", f));
        }
        b.push('\n');
    }
    b.push_str("## Checked\n\n");
    for g in GATES {
        b.push_str(&format!("- [ ] `{}`\n", g));
    }
    b.push_str("\n## Not verified\n\n- \n");
    b
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;

    #[test]
    fn ac6_sync_reports_drift_in_check_and_restores_it_otherwise() {
        let t = tempfile::tempdir().unwrap();
        fs::create_dir_all(t.path().join("docs/reference")).unwrap();
        fs::write(t.path().join("docs/reference/cli.md"), "edited by hand").unwrap();
        fs::write(t.path().join("docs/reference/delphi.1"), "same").unwrap();
        let files = || vec![Generated { path: "docs/reference/cli.md", text: Ok("generated".into()) }, Generated { path: "docs/reference/delphi.1", text: Ok("same".into()) }];
        let s = sync(t.path(), files(), true);
        assert_eq!(s.changed, vec!["docs/reference/cli.md".to_string()]);
        assert_eq!(fs::read_to_string(t.path().join("docs/reference/cli.md")).unwrap(), "edited by hand");
        let s = sync(t.path(), files(), false);
        assert_eq!(s.changed, vec!["docs/reference/cli.md".to_string()]);
        assert_eq!(fs::read_to_string(t.path().join("docs/reference/cli.md")).unwrap(), "generated");
        assert_eq!(sync(t.path(), files(), true), Sync::default());
        let s = sync(t.path(), vec![Generated { path: "docs/reference/x.md", text: Err("broken".into()) }], false);
        assert_eq!(s.errors, vec!["docs/reference/x.md: broken".to_string()]);
    }

    fn tracker_repo(state: &str) -> tempfile::TempDir {
        let t = tempfile::tempdir().unwrap();
        let p = t.path().join(tracker::PATH);
        fs::create_dir_all(p.parent().unwrap()).unwrap();
        fs::write(p, format!("| Spec | Slice | Content | State |\n| :-- | :-- | :-- | :-- |\n| 135 | F1 | the finisher | {} |\n", state)).unwrap();
        t
    }

    #[test]
    fn ac7_the_tracker_check_flags_an_unfinished_row_and_passes_a_built_one() {
        let t = tracker_repo("approved in advance on the plan; not built");
        let e = tracker_check(t.path(), "135-the-forge", "F1").unwrap_err();
        assert!(e.contains("still says"), "{}", e);
        let t = tracker_repo("built (this PR): finisher.rs");
        assert_eq!(tracker_check(t.path(), "135-the-forge", "f1").unwrap().content, "the finisher");
        let e = tracker_check(t.path(), "135-the-forge", "F9").unwrap_err();
        assert!(e.contains("has no row for 135 F9"), "{}", e);
    }

    #[test]
    fn the_body_names_the_trailer_the_row_and_the_gates() {
        let t = tracker_repo("built");
        let row = tracker_check(t.path(), "135-x", "F1").unwrap();
        let b = body(t.path(), "135-x", "F1", Some(&row), &["docs/reference/cli.md".into()]);
        assert!(b.contains("Implements-Spec: specs/135-x.md"));
        assert!(b.contains("**Slice:** the finisher"));
        assert!(b.contains("- `docs/reference/cli.md`"));
        assert!(b.contains("cargo clippy"));
    }

    #[test]
    fn the_checkout_version_is_read_from_the_package_section() {
        let t = tempfile::tempdir().unwrap();
        fs::create_dir_all(t.path().join("crates/delphi")).unwrap();
        fs::write(t.path().join("crates/delphi/Cargo.toml"), "[package]\nname = \"delphi\"\nversion = \"9.9.9\"\n\n[dependencies]\nversion = \"no\"\n").unwrap();
        assert_eq!(checkout_version(t.path()).as_deref(), Some("9.9.9"));
    }
}
